/**
 * Enum describing the genders allowed for animals in this simulation
 * @version 2.2.3
 */
public enum Gender {
	MALE, 
	FEMALE;

	/**
	 * Method which inverts the gender. Useful to see which gender an animal should breed with 
	 * @return the opposite gender
	 */
	public Gender invert() {
		return this == Gender.MALE ? Gender.FEMALE : Gender.MALE;
	}
}

=== Generator.java ===
import java.util.ArrayList;
import java.util.Random;


/**
 * Generator generates the players, and disesease for the sim 
 * 
 * @version 6.8.2
 */
class Generator {
    private Random rand = Randomizer.getRandom(); // Random number generator required for generating probabilities


    /**
     * Function which creates all the players for a field 
     * @param field the field for which all the simulatables will be generated
     * @return the list of all simulatable objects
     */
	public ArrayList<Simulatable> createPlayers(Field field) {

		ArrayList<Simulatable> simulatables = new ArrayList<>();
		for(int row = 0; row < field.getDepth(); row++) {
            for(int col = 0; col < field.getWidth(); col++) {
                Disease disease = generateDisease(); // Get a disease (could be null) to give the animal 
                if(rand.nextDouble() <= Racoon.POPULATION_CONTROLS.getCreationProbability()) {
                    Location location = new Location(row, col);
                    Racoon racoon = new Racoon(true, field, location);
                    racoon.forceDisease(disease);//Give the animal a disease
                    simulatables.add(racoon);
                } 
                else if(rand.nextDouble() <= Hawk.POPULATION_CONTROLS.getCreationProbability()) {
                    Location location = new Location(row, col);
                    Hawk mouse = new Hawk(true, field, location);
                    mouse.forceDisease(disease);
                    simulatables.add(mouse);
                }
                else if(rand.nextDouble() <= Mouse.POPULATION_CONTROLS.getCreationProbability()) {
                    Location location = new Location(row, col);
                    Mouse mouse = new Mouse(true, field, location);
                    mouse.forceDisease(disease);
                    simulatables.add(mouse);
                }
                else if(rand.nextDouble() <= Rat.POPULATION_CONTROLS.getCreationProbability()) {
                    Location location = new Location(row, col);
                    Rat mouse = new Rat(true, field, location);
                    mouse.forceDisease(disease);
                    simulatables.add(mouse);
                }
                else if(rand.nextDouble() <= Squirrel.POPULATION_CONTROLS.getCreationProbability()) {
                    Location location = new Location(row, col);
                    Squirrel mouse = new Squirrel(true, field, location);
                    mouse.forceDisease(disease);
                    simulatables.add(mouse);
                }
                else if(rand.nextDouble() <= Grass.CREATION_PROBABILITY) {//Generate the grass objects
                    Location location = new Location(row, col);
                    Grass mouse = new Grass(field, location);
                    simulatables.add(mouse); 
                } 

                // else leave the location empty.
            }
        }

        return simulatables;

	}

    /** 
     * Genreates a disease for an animal 
     * @return the generated disease. If no disease, returns null 
     */
    private Disease generateDisease() {
        if (rand.nextDouble() <= Rabies.CREATION_PROBABILITY) {
            return new Rabies();
        }
        return null;
    }

}

=== Grass.java ===
import java.util.List;
import java.util.Random;
import java.awt.Color;

/**
 * Class representing grass. 
 * Grass is eatable, simulatable and displayable 
 * 
 * @version 5.3.2
 */
class Grass extends Locatable implements Eatable, Simulatable, Displayable {


	/*
		Population Control variables
	*/
	public static final double CREATION_PROBABILITY = 0.05;
	public static final double BREEDING_PROBABILITY = 0.14;

	private boolean alive; //If the grass is alive
	private int rainAmount; // The amount of rain the grass has recived 

	private static final Random rand = Randomizer.getRandom();


	/**
	 * Initialiser. 
	 * 
	 * @param field the field on which the grass should exist
	 * @param location the location of the grass
	 */ 
	public Grass(Field field, Location location) {
		super(field, location);
		alive = true;
		rainAmount = 0;
	}

	/** 
	 * Implements act, required for all simulatable classes. 
	 * What the animal will do in a simulator cycle 
	 * 
	 * @param newGrass all grass that has been created
	 * @param currentState the simulators current state
	 */ 
	public void act(List<Simulatable> newGrass, SimulatorState currentState) {
		if (currentState.getCurrentWeather() == Weather.Rainy) {
			rainAmount ++; //Increment rain count if it has rained
		}

		if (isAlive()) {
			//If the animal is alive, it should try to grow. 
			Grass newGrasslet = grow();
			if (newGrasslet != null) {
				newGrass.add(newGrasslet);
			}
		}
	}


	/**
	 * Grow, defines how grass should grow
	 */ 
	private Grass grow() {
		Field field = getField();
        List<Location> free = field.getFreeAdjacentLocations(getLocation());//Get adjacent location 
        for(Location i : free) {
        	//If probability is met, generate a new grasslet 
        	if (rand.nextDouble() <= getBreedingProbability(rainAmount)) {
        		rainAmount = 0;
        		Grass newGrasslet = new Grass(field, i);
	        	return newGrasslet;	
        	}

        }
        return null;

	}


	/**
	 * Implements displayable
	 * 
	 * @return the color of grass
	 */
	public Color getColor() {
        return Color.GREEN;
    }

    /**
     * Implmenets displayable
     * since grass cannot get a disease, it does not have a border color
     * @return null
     */
    public Color getBorderColor() {
        return null;
    }

    /**
     * Implements eatable
     * @return the food value of grass
     */
    public int getFoodValue(){
    	return 10;
    }


    /**
     * Implements simulatable 
     * will remove the grass from the field
     */
    public void setDead(){
    	removeFromField();
    	alive = false;
    }


    /**
     * Implements simulatable 
     * @return wether or not the animal is alive
     */
    public boolean isAlive() {
    	return alive;
    }

    /**
     * get the breeding probability. 
     * It is a transformed sigmoid function, which allows for the rain amount to be converted into a probabilty 
     * 0 is relativley little probability + the breeding probability, 10 is the maximum probability
     * @return the probability with which grass should breed
     */ 
    private double getBreedingProbability(int value) {

    	double bottom = 1 + Math.pow(Math.E, -((value / 2) - 2));
    	double rainProbability = (1 / bottom);
    	double allProbability = (5*BREEDING_PROBABILITY + rainProbability) / 2;
    	return BREEDING_PROBABILITY;
    }
}

