public class Hawk extends Animal
{
    // Characteristics shared by all hawks.
    /*
        Population Control variables
    */
    public static PopulationControls POPULATION_CONTROLS = new PopulationControls(
        15, //Breeding age 
        150, //Maxium age
        2, //Maximum litter size
        30, //Maximum hunger
        9, // Initial hunger
        0.26, //Breeding probability
        0.026 // creation probability
    );  

    //An array containing what all Hawks eat (rats and squirrels)
    private static final List<Class> EATS = new ArrayList<Class>(){{
        add(Rat.class);
        add(Squirrel.class);
    }};




    /**
     * Create a Hawk. A Hawk can be created as a new born (age zero
     * and not hungry) or with a random age and food level.
     * 
     * @param randomAge If true, the Hawk will have random age and hunger level.
     * @param field The field currently occupied.
     * @param location The location within the field.
     */
    public Hawk(boolean randomAge, Field field, Location location)
    {
        super(field, location);//Initalise the locatable superaclass
        if(randomAge) {
            age = rand.nextInt(POPULATION_CONTROLS.getMaxAge());
            foodLevel = rand.nextInt(POPULATION_CONTROLS.getInitialHunger());
        } else {
            age = 0;
            foodLevel = POPULATION_CONTROLS.getInitialHunger();
        }
    }

    /**
     * This is what the hawk does most of the time: it hunts for
     * prey. In the process, it might breed, die of hunger,
     * or die of old age.
     * @param field The field currently occupied.
     * @param newAnimals A list to return newly born foxes.
     */
    public void act(List<Simulatable> newAnimals, SimulatorState currentState)
    {
        incrementAge(POPULATION_CONTROLS.getMaxAge());
        Field f = getField();
        if (rand.nextDouble() <= currentState.getAggregatedProbabilityReduction()) {
            incrementHunger();     
            if(isAlive() ) {

                Counter numberOfAnimal = currentState.getCurrentStats(Hawk.class);
                giveBirth(numberOfAnimal, Hawk.class, newAnimals, (Location loc) -> new Hawk(false, f, loc));

                giveNearbyAnimalsDisease();

                Disease currentDisease = getDisease();
                if (currentDisease != null) {
                    foodLevel -= currentDisease.getHungerEffect();
                    age -= currentDisease.getAgeEffect();
                }

                moveToNewLocation(EATS, POPULATION_CONTROLS.getMaxHunger());
            }
        }
    }


    /**
     * Implements displayable
     * 
     * @return the color to display
     */
    public Color getColor() {
        return Color.MAGENTA;
    }


    /**
     * Implements displayable
     * 
     * @return the border color 
     */
    public Color getBorderColor() {
        return getDisease() == null ? null : Color.PINK;
    }


    /**
     * Implements breedable 
     * 
     * @return the gender of the animal
     */ 
    public Gender getGender () {
        return gender;
    }

    /** 
     * Implements breedable 
     * @return the breeding age of the animal
     */ 
